package com.example.banglacall;
import android.accessibilityservice.AccessibilityService; import android.view.accessibility.*; import android.view.*; import android.widget.*; import android.graphics.Color; import android.os.*; import java.util.*; import com.google.mlkit.nl.translate.*;
public class CaptionService extends AccessibilityService {
 static CaptionService instance; private Translator translator; private WindowManager wm; private LinearLayout overlay; private TextView text; private Handler h=new Handler(Looper.getMainLooper()); private String last="",pending=""; private boolean ready=false,busy=false; private int generation=0;
 @Override protected void onServiceConnected(){instance=this;wm=(WindowManager)getSystemService(WINDOW_SERVICE);translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage("en").setTargetLanguage("bn").build());}
 private void show(String message){if(overlay==null){overlay=new LinearLayout(this);overlay.setOrientation(1);overlay.setPadding(18,12,18,12);overlay.setBackgroundColor(0xee172334);text=new TextView(this);text.setTextColor(Color.WHITE);text.setTextSize(19);text.setMaxLines(8);overlay.addView(text);Button stop=new Button(this);stop.setText("বন্ধ / Stop");stop.setOnClickListener(v->stopSession());overlay.addView(stop);WindowManager.LayoutParams p=new WindowManager.LayoutParams(WindowManager.LayoutParams.MATCH_PARENT,WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,android.graphics.PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP;p.y=100;wm.addView(overlay,p);}if(!message.contentEquals(text.getText()))text.setText(message);}
 void showDiagnostic(){generation++;ready=false;busy=false;last="";pending="";show("Diagnostic: enable Live Caption. Only possible view IDs will be shown.");}
 void startSession(){final int g=++generation;ready=false;busy=false;last="";pending="";show("বাংলা মডেল প্রস্তুত হচ্ছে…");translator.downloadModelIfNeeded().addOnSuccessListener(x->{if(g!=generation||!MainActivity.active)return;ready=true;show("English caption-এর অপেক্ষায়…");scan();}).addOnFailureListener(e->{if(g==generation&&MainActivity.active)show("Model download failed. Stop and retry.");});}
 void stopSession(){MainActivity.active=false;MainActivity.diagnostic=false;generation++;ready=false;busy=false;last="";pending="";h.removeCallbacksAndMessages(null);if(overlay!=null){wm.removeView(overlay);overlay=null;text=null;}}
 @Override public void onAccessibilityEvent(AccessibilityEvent e){if(!MainActivity.active&&!MainActivity.diagnostic)return;h.removeCallbacks(scanTask);h.postDelayed(scanTask,180);}
 private final Runnable scanTask=()->scan();
 private void scan(){if(!MainActivity.active&&!MainActivity.diagnostic)return;List<AccessibilityWindowInfo> windows=getWindows();if(windows==null)return;Set<String> candidates=new LinkedHashSet<>();StringBuilder found=new StringBuilder();int[] count={0};for(AccessibilityWindowInfo w:windows){AccessibilityNodeInfo root=w.getRoot();if(root!=null){walk(root,candidates,found,count);root.recycle();}if(count[0]>1500)break;}if(MainActivity.diagnostic){show(candidates.isEmpty()?"Caption ID পাওয়া যায়নি।":"Possible IDs (copy manually):\n"+String.join("\n",candidates));return;}String s=found.toString().trim();if(ready&&!s.isEmpty()&&!s.equals(last)){last=s;pending=s;translateNext();}}
 private void walk(AccessibilityNodeInfo n,Set<String> candidates,StringBuilder found,int[] count){if(++count[0]>1500)return;String p=String.valueOf(n.getPackageName()),id=n.getViewIdResourceName();if(p.equals(getPackageName()))return;if(id!=null&&n.isVisibleToUser()){if(MainActivity.diagnostic){String low=id.toLowerCase(Locale.ROOT);if((low.contains("caption")||low.contains("transcript")||low.contains("subtitle"))&&candidates.size()<5)candidates.add(id);}else if(p.equals(MainActivity.pkg)&&id.equals(MainActivity.selector)){CharSequence t=n.getText();if(t!=null&&found.length()<599){if(found.length()>0)found.append(' ');found.append(t.subSequence(0,Math.min(t.length(),600-found.length())));}}}for(int i=0;i<n.getChildCount()&&count[0]<1500;i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null){walk(c,candidates,found,count);c.recycle();}}}
 private void translateNext(){if(busy||!ready||!MainActivity.active||pending.isEmpty())return;final String s=pending;pending="";busy=true;final int g=generation;translator.translate(s).addOnSuccessListener(result->{if(g!=generation||!MainActivity.active)return;busy=false;show(result);translateNext();}).addOnFailureListener(e->{if(g!=generation||!MainActivity.active)return;busy=false;show("Translation failed; waiting for next caption.");translateNext();});}
 @Override public void onInterrupt(){stopSession();} @Override public void onDestroy(){stopSession();if(translator!=null)translator.close();instance=null;super.onDestroy();}
}